/**
 * RadioGroup. Each option is a recessed hole beside
 * its label; choosing one lights a pip inside the hole. Rebuilt after the
 * original ECHO repo's radio: every option used to be its own molded pill
 * cap, so a three-way choice put three raised buttons on the panel and read
 * as three actions instead of one choice. A choice is not a button — the
 * hole is the control, the text is the label, and only the chosen one lights.
 * Composes var(--echo-*).
 */
.echo-radio-group {
  display: flex;
  /*
   * The group used to be a single non-wrapping row, so on a phone the
   * third "Output routing" option — "Both" — was simply cut off by the panel
   * edge. A user could not see or reach one of three choices.
   *
   * `align-items: stretch` is the other half of the fix: "Line out" wraps to
   * two lines at that width, and without it the pills in one group ended up
   * different heights, which reads as three unrelated controls rather than as
   * one choice.
   */
  flex-wrap: wrap;
  align-items: stretch;
  gap: var(--echo-space-5) var(--echo-space-10);
}

.echo-radio-group[data-orientation="vertical"] {
  flex-direction: column;
  align-items: flex-start;
  gap: var(--echo-space-5);
}

.echo-radio {
  display: inline-flex;
  align-items: center;
  /* Never wider than the group, so a long option wraps instead of clipping. */
  max-width: 100%;
  /* A 24px row: the target is the whole line, label included. */
  min-height: 24px;
  gap: var(--echo-space-5);
  padding: 0;
  border: 0;
  background: none;
  cursor: pointer;
  font-family: var(--echo-font-machine, ui-sans-serif, system-ui, sans-serif);
  font-size: var(--echo-text-sm);
  color: var(--echo-text-dim);
  transition: color var(--echo-duration-swap) ease;
}

.echo-radio[data-checked] {
  color: var(--echo-text);
}
@media (hover: hover) {
  .echo-radio:hover {
    color: var(--echo-text);
  }
}

.echo-radio:focus-visible {
  outline: none;
}

/* Focus rings the hole, not the whole line — the hole is the control. */
.echo-radio:focus-visible .echo-radio__control {
  /* Drawn only in forced colors, which drops the shadow ring. */
  outline: 2px solid transparent;
  outline-offset: 2px;
  box-shadow:
    inset 0 2px 4px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.7 * var(--echo-shade, 1) * 100%), transparent),
    inset 0 0 0 var(--echo-line-width, 0px) var(--echo-line, transparent),
    0 0 0 2px var(--echo-surface),
    0 0 0 4px var(--echo-accent-ink, var(--echo-accent-glow));
}

.echo-radio[data-disabled] {
  opacity: 0.45;
  cursor: default;
}

/* The recessed hole the pip sits in. */
.echo-radio__control {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  box-sizing: border-box;
  /* The hole must not be squeezed by a label that wraps beside it. */
  flex-shrink: 0;
  width: 20px;
  height: 20px;
  border-radius: var(--echo-radius-full);
  background: var(--echo-drawn-hollow, linear-gradient(
    160deg,
    color-mix(in oklab, var(--echo-well) 72%, var(--echo-shade-ink, black)),
    color-mix(in oklab, var(--echo-lcd) 88%, var(--echo-shade-ink, black))
  ));
  /*
   * The last shadow is the bezel: a 1px rim of chassis plastic around the
   * hole. Without it a hole the colour of the page ground has no edge and
   * vanishes — it only read on a raised panel.
   */
  box-shadow:
    inset 0 calc(2px + 1px * var(--radio-depth, 0)) calc(4px + 2px * var(--radio-depth, 0)) color-mix(in oklab, var(--echo-cast-ink, black) calc(0.7 * var(--echo-shade, 1) * 100%), transparent),
    inset 0 -1px 0 rgb(255 255 255 / calc(0.06 * var(--echo-gloss, 1))),
    inset 0 0 0 var(--echo-line-width, 0px) var(--echo-line, transparent),
    0 0 0 1px color-mix(in oklab, var(--echo-cap) 85%, transparent);
}

/*
 * Base UI renders the Indicator only while checked, so the pip IS the state.
 * It is the Record button's lit cap in miniature — the same primary-cap stops,
 * a lit top edge — and it stays inside the hole: no halo.
 */
.echo-radio__pip {
  display: block;
  width: 10px;
  height: 10px;
  border-radius: var(--echo-radius-full);
  /* Drawn, the chosen one is filled in solid ink. */
  background: var(--echo-drawn-ink, linear-gradient(
    180deg,
    var(--echo-primary-cap-top) 0%,
    var(--echo-primary-cap-mid) 45%,
    var(--echo-primary-cap-base) 100%
  ));
  box-shadow: inset 0 1px 0 rgb(255 255 255 / calc(0.45 * var(--echo-gloss, 1)));
  /* Chosen, the pip blooms into its hole, overshooting and settling; the one
     let go drains away quickly. Base UI holds it mounted until it has. */
  transition:
    transform var(--echo-duration-pop) var(--echo-ease-pop),
    opacity var(--echo-duration-tick) ease;
}
.echo-radio__pip[data-starting-style] {
  transform: scale(0);
  opacity: 0;
}
.echo-radio__pip[data-ending-style] {
  transform: scale(0.2);
  opacity: 0;
  transition-duration: var(--echo-duration-swap);
  transition-timing-function: ease-in;
}

/* The hole answers the hand: its rim catches the light under the pointer. */
.echo-radio__control {
  transition: box-shadow var(--echo-duration-tick) ease;
}
@media (hover: hover) {
  .echo-radio:not([data-disabled]):not(:focus-visible):hover .echo-radio__control {
    box-shadow:
      inset 0 calc(2px + 1px * var(--radio-depth, 0)) calc(4px + 2px * var(--radio-depth, 0)) color-mix(in oklab, var(--echo-cast-ink, black) calc(0.7 * var(--echo-shade, 1) * 100%), transparent),
      inset 0 -1px 0 rgb(255 255 255 / calc(0.06 * var(--echo-gloss, 1))),
      0 0 0 1px color-mix(in oklab, var(--echo-cap-highlight) 70%, transparent);
  }
}
/* Pressed, the hole deepens on the library's stroke (--press from the
   radio's physics, --load while held) and the lit pip sinks with it. */
.echo-radio__control {
  --radio-depth: calc(var(--press, 0) + 0.5 * var(--load, 0));
}
.echo-radio__pip {
  translate: 0 calc(0.6px * var(--radio-depth));
}

.echo-radio__label {
  min-width: 0;
  overflow-wrap: anywhere;
  /* 1 clips descenders once the label is allowed to wrap to two lines. */
  line-height: var(--echo-leading-tight, 1.25);
}

@media (prefers-reduced-motion: reduce) {
  .echo-radio,
  .echo-radio__pip,
  .echo-radio__control {
    transition: none;
  }
}

/*
 * Coarse-pointer targets.
 *
 * These already clear WCAG 2.2 2.5.8's 24px. This is the 44px both
 * platform guidelines use — a fingertip rather than conformance. Gated on
 * `@media (pointer: coarse)`, so the desktop rendering does not move.
 *
 * Where a control's visual size is the design (a 24px checkbox, a 10px pip),
 * the target is grown with the same transparent pseudo-element as the 24px minimum,
 * not by growing the control.
 */
@media (pointer: coarse) {
  .echo-radio {
    min-height: 44px;
  }
}

/*
 * Forced colors (Windows High Contrast) drops gradients and shadows, which is
 * everything that draws this control's state. System colors draw it instead;
 * nothing here sets forced-color-adjust: none, so focus outlines still show.
 */
@media (forced-colors: active) {
  .echo-radio__control {
    border: var(--echo-border-thick, 2px) solid ButtonText;
  }
  .echo-radio__pip {
    background: Highlight;
  }
}

"use client";

/**
 * RadioGroup. Base UI RadioGroup behavior
 * (roving focus, arrow-key selection, form semantics) skinned as a row of
 * recessed holes beside their labels, the chosen one lit by a pip.
 *
 * Compound API: <RadioGroup><RadioGroup.Item value="a">Label</RadioGroup.Item></RadioGroup>.
 *
 * The label lives INSIDE Radio.Root (which renders the role=radio button), so
 * the text IS the accessible name and the whole line is the hit target. A
 * wrapping <label> would not associate with a button and would leave the radio
 * unnamed.
 *
 * Sound rides on the group's onValueChange rather than useTactile: Base UI's
 * Root owns the click, so wrapping the callback avoids clobbering it.
 *
 * NOTE: the package is `@base-ui/react`, NOT `@base-ui-components/react`.
 */
import { forwardRef, type DOMAttributes, type ReactNode } from "react";
import { RadioGroup as BaseRadioGroup } from "@base-ui/react/radio-group";
import { Radio as BaseRadio } from "@base-ui/react/radio";
import type { EchoChangeEvent, EchoInterop } from "echo-ui-core/types";
import { useSoundOptional } from "echo-ui-core/sound";
import { mergeHandlers, useCapPhysics } from "echo-ui-core/tactile";
import "./radio-group.css";

export type RadioGroupOrientation = "horizontal" | "vertical";

/**
 * A control has to have a name: `aria-label`, or
 * `aria-labelledby` pointing at visible text. Leaving both out is a type
 * error, so it gets decided rather than forgotten.
 */
type AccessibleName =
  | { "aria-label": string; "aria-labelledby"?: string }
  | { "aria-labelledby": string; "aria-label"?: string };

/**
 * `value` is narrowed to `string`, not left as Base UI's `unknown`.
 *
 * Base UI types a radio group's value as unknown because it will carry any
 * value you hand an Item. Echo's Select had already made the call to narrow to
 * string, and shipping two sibling value-selectors whose callbacks need
 * different handling is incoherence a whole screen of controls exposes:
 * `onValueChange={setRouting}` typechecks on one and not the other, for no
 * reason a consumer can see. A radio group in a form is string-valued.
 */
/**
 * Narrowed deliberately.
 *
 * This used to be `Omit<Skin<ComponentProps<typeof BaseRadioGroup>>, …>`:
 * a wholesale passthrough of Base UI's props, which made Echo's public API a
 * downstream of Base UI's internals AND accepted `className`, the open
 * API `PRINCIPLES.md` says Echo does not have. The public-API leak check could
 * not see it, because a `typeof` passthrough has no dot after the alias.
 */
interface RadioGroupOwnProps extends EchoInterop {
  value?: string;
  defaultValue?: string;
  /** Lay the options out in a row or a stack. Default "horizontal". */
  orientation?: RadioGroupOrientation;
  /** Fired with the newly selected value. */
  onValueChange?: (
    value: string,
    eventDetails: EchoChangeEvent,
  ) => void;
  children?: ReactNode;
}

export type RadioGroupProps = RadioGroupOwnProps & AccessibleName;

/** `forwardRef`, not a `ref` prop — see the note on `Field`. */
const RadioGroupRoot = forwardRef<HTMLDivElement, RadioGroupProps>(function RadioGroupRoot(
  { onValueChange, orientation = "horizontal", ...props },
  ref,
) {
  const sound = useSoundOptional();
  return (
    <BaseRadioGroup
      ref={ref}
      className="echo-radio-group"
      data-orientation={orientation}
      onValueChange={(value, eventDetails) => {
        sound?.play("select");
        onValueChange?.(value as string, eventDetails);
      }}
      {...props}
    />
  );
});

/**
 * The same narrowing for an item: its own props, not Base UI's, and no
 * `className`. `value` is what the group reports when this one is chosen.
 */
interface RadioGroupItemProps extends EchoInterop {
  value: string;
  children?: ReactNode;
}

const RadioGroupItem = forwardRef<HTMLButtonElement, RadioGroupItemProps>(function RadioGroupItem(
  { children, ...props },
  ref,
) {
  // The hole takes the library's press (useCapPhysics) without moving: it
  // deepens as the stroke lands and while held (--press, --load), and the lit
  // pip sinks with it. The row hears the pointer; the hole is what answers.
  const hole = useCapPhysics<HTMLSpanElement>({ lift: 0, travel: 0, tilt: 0 });
  const live = (e: { currentTarget: Element }) => !e.currentTarget.hasAttribute("data-disabled");
  const own: DOMAttributes<HTMLElement> = {
    onPointerDown: (e) => live(e) && hole.handlers.onPointerDown?.(e as never),
    onPointerUp: (e) => hole.handlers.onPointerUp?.(e as never),
    onPointerLeave: (e) => hole.handlers.onPointerLeave?.(e as never),
    onPointerCancel: (e) => hole.handlers.onPointerCancel?.(e as never),
    onBlur: (e) => hole.handlers.onBlur?.(e as never),
    // Space chooses a radio; Enter and the arrows don't press it.
    onKeyDown: (e) => e.key === " " && live(e) && hole.handlers.onKeyDown?.(e as never),
    onKeyUp: (e) => e.key === " " && hole.handlers.onKeyUp?.(e as never),
  };

  return (
    <BaseRadio.Root ref={ref} className="echo-radio" {...props} {...mergeHandlers(own, props as Record<string, unknown>)}>
      <span ref={hole.ref} className="echo-radio__control" aria-hidden="true">
        <BaseRadio.Indicator className="echo-radio__pip" />
      </span>
      <span className="echo-radio__label">{children}</span>
    </BaseRadio.Root>
  );
});

// Assembled into `RadioGroup` in index.ts, which isn't a client module.
export { RadioGroupRoot, RadioGroupItem };

/**
 * The entry point for RadioGroup, deliberately NOT a client module: the parts are
 * attached here, from named client exports. Attached inside the "use client"
 * file, they didn't survive a server component's import, so RadioGroup.Item was
 * undefined in a Next.js page or layout and the build failed.
 */
import { RadioGroupRoot, RadioGroupItem } from "./radio-group";

export const RadioGroup = Object.assign(RadioGroupRoot, {
  Item: RadioGroupItem,
});
export type { RadioGroupProps, RadioGroupOrientation } from "./radio-group";
